// Inicializa dos arrays vacíos: 'steps' para almacenar la información de los pasos y 'tokens' para almacenar la información de los tokens.
// Estos arrays se llenarán con los datos extraídos de la entrada.
const steps = [];
const tokens = [];
// Inicializa una variable 'totalCost' a 0.
// Esta variable se usará para rastrear y acumular el costo total a medida que se procesan los datos.
let totalCost = 0;

// Inicia un bucle 'for...of' para iterar sobre cada 'item' en el objeto de entrada '$input.all()'.
// '$input.all()' presumiblemente devuelve una colección de elementos a procesar.
for (const item of $input.all()) {
  // Obtiene la propiedad 'json' de cada 'item' y la asigna a la variable 'data'.
  // Se espera que 'data' contenga la información principal a procesar.
  let data = item.json;

  // Verifica si la variable 'data' es un array.
  // Esto es para manejar casos donde la entrada JSON es una lista de objetos.
  if (Array.isArray(data)) {
    // Si 'data' es un array, inicia otro bucle 'for...of' para iterar sobre cada 'obj' dentro del array 'data'.
    // Cada 'obj' representa un elemento individual que necesita ser procesado.
    for (const obj of data) {
      // Comprueba si 'obj' tiene una propiedad 'intermediateSteps' y si esta es un array.
      // 'intermediateSteps' parece contener una secuencia de acciones o etapas.
      if (obj.intermediateSteps && Array.isArray(obj.intermediateSteps)) {
        // Si 'intermediateSteps' existe y es un array, itera sobre cada 'step' en 'obj.intermediateSteps'.
        // Cada 'step' representa una acción o etapa intermedia específica.
        for (const step of obj.intermediateSteps) {
          // Verifica si el 'step' actual tiene una propiedad 'action'.
          // La propiedad 'action' contendría los detalles de la acción realizada en este paso.
          if (step.action) {
            // Si 'step.action' existe, crea un nuevo objeto con las propiedades 'tool', 'toolInput' y 'observation'
            // extraídas de 'step.action' y 'step', y lo añade al array 'steps'.
            // 'tool' podría ser la herramienta utilizada, 'toolInput' la entrada para esa herramienta, y 'observation' el resultado.
            steps.push({
              tool: step.action.tool,
              toolInput: step.action.toolInput,
              observation: step.observation
            });
          }
        }
      }

      // Comprueba nuevamente si 'obj' tiene una propiedad 'intermediateSteps' y si esta es un array.
      // Esta sección se enfoca en extraer información sobre tokens y costos.
      if (obj.intermediateSteps && Array.isArray(obj.intermediateSteps)) {
        // Itera sobre cada 'step' en 'obj.intermediateSteps'.
        for (const step of obj.intermediateSteps) {
          // Verifica si 'step' tiene una propiedad 'action', si 'step.action' tiene 'messageLog' y si 'messageLog' es un array.
          // 'messageLog' podría contener registros de mensajes intercambiados, que a su vez tienen metadatos sobre el uso.
          if (step.action && step.action.messageLog && Array.isArray(step.action.messageLog)) {
            // Itera sobre cada 'message' en 'step.action.messageLog'.
            // Cada 'message' representa un mensaje individual en el registro.
            for (const message of step.action.messageLog) {
              // Verifica si 'message' tiene 'kwargs', si 'kwargs' tiene 'response_metadata', y si 'response_metadata' tiene 'usage'.
              // Esta estructura anidada lleva a la información de uso de tokens y costos.
              if (message.kwargs && message.kwargs.response_metadata && message.kwargs.response_metadata.usage) {
                // Asigna el objeto 'usage' a una constante para facilitar el acceso a sus propiedades.
                const usage = message.kwargs.response_metadata.usage;
                // Crea un nuevo objeto con información detallada de los tokens ('prompt_tokens', 'completion_tokens', 'total_tokens'),
                // el costo ('cost') y el nombre del modelo ('model_name'), extraído de 'usage' y 'message.kwargs.response_metadata',
                // y lo añade al array 'tokens'.
                tokens.push({
                  prompt_tokens: usage.prompt_tokens,
                  completion_tokens: usage.completion_tokens,
                  total_tokens: usage.total_tokens,
                  cost: usage.cost,
                  model_name: message.kwargs.response_metadata.model_name
                });

                // Verifica si 'usage.cost' es un número.
                // Esto es para asegurar que solo se sumen valores numéricos al costo total.
                if (typeof usage.cost === 'number') {
                  // Si 'usage.cost' es un número, lo suma a la variable 'totalCost'.
                  // Esto acumula el costo de cada operación.
                  totalCost += usage.cost;
                }
              }
            }
          }
        }
      }
    }
  } else {
    // Si 'data' no es un array, significa que es un solo objeto. Se procesa de manera similar a los objetos dentro del array.
    // Esta sección es un espejo de la lógica anterior, pero aplicada directamente a 'data' en lugar de a 'obj'.

    // Comprueba si 'data' tiene una propiedad 'intermediateSteps' y si esta es un array.
    if (data.intermediateSteps && Array.isArray(data.intermediateSteps)) {
      // Itera sobre cada 'step' en 'data.intermediateSteps'.
      for (const step of data.intermediateSteps) {
        // Verifica si el 'step' actual tiene una propiedad 'action'.
        if (step.action) {
          // Añade la información del paso al array 'steps'.
          steps.push({
            tool: step.action.tool,
            toolInput: step.action.toolInput,
            observation: step.observation
          });
        }
      }
    }

    // Comprueba nuevamente si 'data' tiene una propiedad 'intermediateSteps' y si esta es un array para extraer tokens y costos.
    if (data.intermediateSteps && Array.isArray(data.intermediateSteps)) {
      // Itera sobre cada 'step' en 'data.intermediateSteps'.
      for (const step of data.intermediateSteps) {
        // Verifica la estructura anidada para acceder a 'messageLog'.
        if (step.action && step.action.messageLog && Array.isArray(step.action.messageLog)) {
          // Itera sobre cada 'message' en 'step.action.messageLog'.
          for (const message of step.action.messageLog) {
            // Verifica la estructura anidada para acceder a 'usage'.
            if (message.kwargs && message.kwargs.response_metadata && message.kwargs.response_metadata.usage) {
              // Asigna 'usage' a una constante.
              const usage = message.kwargs.response_metadata.usage;
              // Añade la información de los tokens y el costo al array 'tokens'.
              tokens.push({
                prompt_tokens: usage.prompt_tokens,
                completion_tokens: usage.completion_tokens,
                total_tokens: usage.total_tokens,
                cost: usage.cost,
                model_name: message.kwargs.response_metadata.model_name
              });

              // Verifica si 'usage.cost' es un número antes de sumarlo.
              if (typeof usage.cost === 'number') {
                // Acumula el costo en 'totalCost'.
                totalCost += usage.cost;
              }
            }
          }
        }
      }
    }
  }
}

// Devuelve un array que contiene un solo objeto.
// Este objeto tiene una propiedad 'json' que, a su vez, contiene los arrays 'steps' y 'tokens' procesados,
// y el 'total_cost' calculado.
// Esta es la salida final del script.
return [{
  json: {
    steps: steps,
    tokens: tokens,
    total_cost: totalCost
  }
}];

